const cons = $('Consistency Checker').first().json;
const cls = $('Collect Classifications').first().json.classifications;
const pad = c => String(c ?? '').replace(/\D/g, '').slice(0, 6).padStart(6, '0');

const tariff = {};
$('Tariff Reference').all().forEach(r => { tariff[pad(r.json.hs6 ?? r.json.HS6)] = r.json; });
const restricted = {};
$('Restricted List').all().forEach(r => { restricted[pad(r.json.hs6 ?? r.json.HS6)] = r.json.reason; });

const MIN_CONF = 0.8; // first guess, tune in Sprint 3
const reasons = cons.consistency_issues.map(i =>
  `${i.type}${i.line ? ` (line ${i.line})` : ''}: ${i.detail}`);

const lines = cls.map(c => {
  const o = c.output || c;
  const inv = cons.invoice.items.find(it => it.line === o.line) || {};
  const all = (o.candidates || []).map(x => ({ ...x, hs6: pad(x.hs6), in_tariff: !!tariff[pad(x.hs6)] }));
  const first = all[0];
  // alternates that are not in the tariff are dropped, only the top code decides the route
  const cands = first ? [first, ...all.slice(1).filter(x => x.in_tariff)] : [];
  let top = first;

  if (!top) reasons.push(`Line ${o.line}: no HS code suggested`);
  if (top && !top.in_tariff) reasons.push(`Line ${o.line}: code ${top.hs6} not found in tariff (possible invented code)`);
  if (o.needs_review) reasons.push(`Line ${o.line}: ${o.review_reason || 'classifier asked for review'}`);
  if (top && Number(top.confidence) < MIN_CONF) reasons.push(`Line ${o.line}: low confidence (${top.confidence})`);
  if (top && restricted[top.hs6]) reasons.push(`Line ${o.line}: restricted goods, ${restricted[top.hs6]}`);

  const lineUnsure = !top || !top.in_tariff || o.needs_review || Number(top.confidence) < MIN_CONF;
  const rate = top && !lineUnsure && tariff[top.hs6] ? Number(tariff[top.hs6].duty_rate_percent) : NaN;
  const duty = isNaN(rate) ? null : +(Number(inv.line_total || 0) * rate / 100).toFixed(2);

  return {
    line: o.line, description: String(inv.description ?? '').replace(/\n/g, ' '),
    quantity: inv.quantity, value: inv.line_total,
    currency: cons.invoice.currency, origin: cons.invoice.origin_country,
    suggested_hs6: top && !lineUnsure ? top.hs6 : null, needs_broker_classification: lineUnsure, candidates: cands,
    duty_rate_percent: isNaN(rate) ? null : rate, expected_duty: duty
  };
});

const ready = reasons.length === 0;
return [{ json: {
  shipment_id: cons.shipment_id,
  ready, route: ready ? 'ready_for_broker' : 'human_review',
  reasons, lines
} }];

const d = $input.first().json;
const status = d.ready ? 'READY FOR BROKER' : 'HUMAN REVIEW NEEDED';
const unsure = l => l.needs_broker_classification === true;

let t = `TradeCheck AI report\nShipment: ${d.shipment_id}\nStatus: ${status}\nGenerated: ${new Date().toISOString()}\n\n`;
t += d.reasons.length
  ? 'Issues found:\n' + d.reasons.map((r, i) => `${i + 1}. ${r}`).join('\n')
  : 'No issues found.';
t += '\n\nDeclaration draft (NOT submitted):\n';
d.lines.forEach(l => {
  if (l.line === 0 || l.line === null || l.line === undefined) {
    t += `\nNo invoice lines could be read. The broker must classify all goods manually.\n`;
    return;
  }
  t += `\nLine ${l.line}: ${l.description} | qty ${l.quantity} | value ${l.value} ${l.currency} | origin ${l.origin}\n`;
  if (unsure(l)) {
    t += `  Suggested HS: NO CODE SUGGESTED, broker to classify\n`;
    (l.candidates || []).forEach((c, i) => {
      t += `  Rejected candidate ${i + 1}: ${c.hs6} (confidence ${c.confidence}), not reliable\n`;
    });
  } else {
    t += `  Suggested HS: ${l.suggested_hs6 ?? 'none'} | estimated duty: ${l.expected_duty ?? 'n/a'} ${l.currency}\n`;
    l.candidates.forEach((c, i) => {
      t += `  Option ${i + 1}: ${c.hs6} (confidence ${c.confidence}) ${c.reason}\n`;
      t += `    Tariff text: ${c.heading_text_quoted}\n`;
    });
  }
});
t += '\nGenerated by TradeCheck AI using Google Gemini. This draft is for a licensed customs broker. TradeCheck AI never submits declarations. Duty is an estimate.';
return [{ json: { ...d, status, report_text: t, title: `TradeCheck ${d.shipment_id} ${status}` } }];

const get = n => { try { return $(n).first().json.text || ''; } catch (e) { return ''; } };
const text = [get('Invoice text'), get('Packing_List'), get('Origin Text')].join('\n\n');
return [{ json: { text } }];
